package commands

import (
	"os"
	"path/filepath"

	"github.com/spf13/cobra"
	"github.com/spf13/cobra/doc"
)

// skillsConfig describes the agent skill generated by `genskills`.
var skillsConfig = doc.SkillsConfig{
	Name:        "suprsend-cli",
	Description: "SuprSend CLI tool for managing SuprSend account and resources from the command line — workspaces, workflows, templates, categories, events, schemas, and translations. Use ONLY when the user wants the agent to RUN a `suprsend ...` command (e.g. \"push my template\", \"pull all workflows\", \"sync staging to prod\", \"generate Python types\") or asks about a specific CLI command's flags/behavior (\"what does `suprsend template commit --dry-run` do?\"). Do NOT load for documentation, lookup, or conceptual SuprSend questions (\"how does batching work\", \"what is a variant\", \"explain delivery nodes\") — load `suprsend-docs-support` for those. Do NOT load when the user is authoring workflow or template JSON without invoking the CLI — load `suprsend-workflow-schema` or `suprsend-template-schema` for those.",
	Metadata: map[string]string{
		"author":   "suprsend",
		"category": "cli",
	},
	Notes: []string{
		"`list` commands default to `-o pretty` (a human-friendly table) and also accept `-o json` and `-o yaml`. `workflow get`, `schema get`, `event get` and `translation get` default to `-o json`, accept `-o yaml`, and reject `-o pretty`; `template get` defaults to `-o json` and also accepts `yaml` and `pretty`.",
		"`push`, `pull`, `commit`, `enable`, `disable`, `sync` and `generate-types` always print their result on stdout, whether or not it is a terminal: a header naming the workspace, host and profile, one line per item with its status, any warnings, and a summary. Statuses: `pushed` (saved as draft), `committed` (live), `unchanged` (commit requested, but the draft already matched live), `pulled`, `would-push` / `would-commit` (dry run), `skipped`, `failed`. With `-o json` the result is one JSON object with `command`, `workspace`, `host`, `profile`, `dry_run`, `ok`, `counts`, `items` and `warnings`.",
		"When stderr is not a terminal (piped, as in most agent and CI shells) or with `-o json`, log lines are hidden (pass `-v info` to see them; warnings still appear in the result) and an error is one JSON object on stderr with `error`, `code` and `hint`. When a run over several items fails, the error lists each failed item and its reason, also as `details.failures`.",
		"Exit codes: 0 success; 1 API error, or any failed item in a run over several items; 2 local validation (unreadable file, invalid JSON or JSON Schema, an invalid workflow on commit); 3 auth; 4 not found (a resource or the workspace); 5 rate limited; 64 invalid usage. A command on a single resource exits with that resource's code.",
		"Workspace: `-w` beats `SUPRSEND_WORKSPACE`, which beats the active profile's `workspace`; the fallback is `staging`. Write commands warn when they fall back to `staging`, and check that the workspace exists before writing (a typo fails with `unknown workspace` and a did-you-mean hint, exit 4). Run `suprsend whoami --check` to see the profile, host and workspace commands will use. The service token comes from `--service-token`, else `SUPRSEND_SERVICE_TOKEN`, else the profile.",
		"On `push`, `commit`, `enable` and `disable`, `--dry-run` never calls the API. `push` reads and parses the local files (schemas also get a local JSON Schema compile; `category push` parses `categories.json` but only lists the translation files); `commit`, `enable` and `disable` read nothing. They only report what would happen, and the workspace isn't checked. It is not a server-side validation. `sync --dry-run` is different: it still pulls the source workspace and overwrites local files, and only skips the destination.",
		"Confirmation prompts (commit, `push --commit`, `sync`, `workflow disable`) only appear when stdin is a TTY. In non-interactive shells (CI, agents) these commands proceed immediately without asking, even without `--force`, so check the target with `suprsend whoami --check` first.",
		"Committing when the draft already matches live is not an error: `commit`, `push --commit` and `sync` report `unchanged` and exit 0, so re-running them is safe.",
		"Requests are retried up to twice when the connection drops or the API answers 429, 502, 503 or 504. If a commit loses its connection on every attempt, the error says the commit status is unknown; run the same command again, and it reports `unchanged` if the commit went through.",
		"`sync` pushes **and commits** every synced asset in the destination (default `--to production`), so the changes go live immediately.",
		"To give an AI tool direct access to SuprSend, use the hosted MCP server at `https://mcp.suprsend.com/mcp` (sign in with a SuprSend account; for Claude Code: `claude mcp add --transport http suprsend https://mcp.suprsend.com/mcp`) or the `suprsend/claude-plugin` / `suprsend/agent-plugin` plugins. The CLI's own `start-mcp-server` command is deprecated and not covered here.",
		"The `profile` command and its subcommands (add, list, modify, remove, use) are only needed for self-hosted/BYOC SuprSend instances, managing multiple accounts, or setting a default workspace (`profile modify --name <p> --workspace <ws>`). SaaS users do not need them. To switch between workspaces within the same account, use the `--workspace` flag or `SUPRSEND_WORKSPACE`.",
	},
}

// generateSkills writes the skill to <dir>/<skillsConfig.Name>/ (SKILL.md plus
// one references/<command>.md page per visible command). GenSkillsDir only
// creates and overwrites files, so the references directory is cleared first;
// otherwise pages for removed or renamed commands would linger. Hidden
// commands (gendocs, genskills) are left out by the generator.
func generateSkills(dir string) error {
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return err
	}
	if err := os.RemoveAll(filepath.Join(dir, skillsConfig.Name, "references")); err != nil {
		return err
	}
	return doc.GenSkillsDir(rootCmd, dir, skillsConfig)
}

var genSkillsCmd = &cobra.Command{
	Use:    "genskills [dir]",
	Hidden: true,
	Short:  "Generate the agent skill (SKILL.md and references)",
	Args:   cobra.ExactArgs(1),
	RunE: func(cmd *cobra.Command, args []string) error {
		return generateSkills(args[0])
	},
}

func init() {
	genSkillsCmd.SetHelpFunc(func(command *cobra.Command, strings []string) {
		command.Flags().MarkHidden("workspace")
		command.Flags().MarkHidden("service-token")
		command.Flags().MarkHidden("output")
		command.Flags().MarkHidden("verbosity")
		command.Flags().MarkHidden("no-color")
		command.Flags().MarkHidden("config")
		command.Parent().HelpFunc()(command, strings)
	})

	rootCmd.AddCommand(genSkillsCmd)
}
